-- PostgreSQL 17. Execute uma vez, com backup, antes de iniciar com DDL_AUTO=validate.
-- Compatível com o esquema legado do tg. Falha sem modificar dados se CPFs normalizados colidirem.
BEGIN;
CREATE TABLE IF NOT EXISTS clientes (id bigint generated by default as identity primary key, nome varchar(255) not null,
 data_nascimento date,cpf varchar(14),rg varchar(20),orgao_expedidor varchar(20),telefone varchar(20),email varchar(150),
 endereco varchar(255),numero varchar(10),bairro varchar(255),cidade varchar(255),estado varchar(2),cep varchar(9),filiacao varchar(255),constraint uk_cliente_cpf unique(cpf));
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM clientes WHERE cpf IS NOT NULL GROUP BY regexp_replace(cpf,'[^0-9]','','g') HAVING count(*)>1) THEN
 RAISE EXCEPTION 'CPFs duplicados após normalização. Corrija antes da migração.'; END IF;
END $$;
UPDATE clientes SET cpf=regexp_replace(cpf,'[^0-9]','','g') WHERE cpf IS NOT NULL;
ALTER TABLE clientes ADD COLUMN IF NOT EXISTS revisado boolean NOT NULL DEFAULT false;
ALTER TABLE clientes ADD COLUMN IF NOT EXISTS versao bigint DEFAULT 0;
CREATE TABLE IF NOT EXISTS documentos(id bigint generated by default as identity primary key,nome_original varchar(255) not null,
 nome_armazenado varchar(255) not null,caminho_arquivo varchar(255) not null,tipo_arquivo varchar(255) not null,tamanho_arquivo bigint not null,
 data_upload timestamp not null,cliente_id bigint not null references clientes(id));
CREATE TABLE IF NOT EXISTS resultados_ocr(id bigint generated by default as identity primary key,resultado_json text,
 data_processamento timestamp not null,status varchar(255) not null,documento_id bigint not null unique references documentos(id));
CREATE TABLE IF NOT EXISTS usuarios(id bigint generated by default as identity primary key,nome varchar(255) not null,email varchar(255) not null unique,
 senha_hash varchar(255) not null,perfil varchar(255) not null,oab varchar(255),ativo boolean not null default true);
CREATE TABLE IF NOT EXISTS sessoes(id bigint generated by default as identity primary key,token_hash varchar(64) not null unique,
 usuario_id bigint not null references usuarios(id),expira_em timestamp with time zone not null);
CREATE TABLE IF NOT EXISTS auditoria(id bigint generated by default as identity primary key,data_hora timestamp with time zone not null,
 usuario varchar(255) not null,modulo varchar(255) not null,acao varchar(255) not null,registro varchar(255),origem varchar(255));
CREATE TABLE IF NOT EXISTS modelos(id bigint generated by default as identity primary key,codigo varchar(255) not null unique,nome varchar(255) not null,
 categoria varchar(255),area varchar(255),tags varchar(255),descricao varchar(255),conteudo text not null,status varchar(255) not null,
 numero_versao integer not null default 0,autor varchar(255),atualizado_em timestamp with time zone,revisao bigint);
CREATE TABLE IF NOT EXISTS modelo_versoes(id bigint generated by default as identity primary key,modelo_id bigint not null references modelos(id),
 numero integer not null,conteudo text not null,autor varchar(255),criado_em timestamp with time zone,unique(modelo_id,numero));
CREATE TABLE IF NOT EXISTS minutas(id bigint generated by default as identity primary key,cliente_id bigint not null references clientes(id),
 modelo_versao_id bigint not null references modelo_versoes(id),conteudo text not null,status varchar(255),autor varchar(255),revisor varchar(255),
 criado_em timestamp with time zone,revisado_em timestamp with time zone,revisao bigint);
CREATE TABLE IF NOT EXISTS configuracoes(id bigint generated by default as identity primary key,chave varchar(255) not null unique,valor text);
CREATE INDEX IF NOT EXISTS idx_documentos_cliente ON documentos(cliente_id);
CREATE INDEX IF NOT EXISTS idx_minutas_cliente ON minutas(cliente_id);
CREATE INDEX IF NOT EXISTS idx_auditoria_data ON auditoria(data_hora);
CREATE INDEX IF NOT EXISTS idx_sessoes_expira ON sessoes(expira_em);
COMMIT;
